// Automatic checks generated by App Builder. Run with: flutter test
// They open every page at phone size and tap every button that goes to a page.
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:my_app/main.dart';
import 'package:my_app/pages/welcome_page.dart';
import 'package:my_app/pages/signin_page.dart';
import 'package:my_app/pages/home_page.dart';

/// Shows [app] on a typical phone screen (360 x 800) and waits until it settles.
Future<void> openOnPhone(WidgetTester tester, Widget app) async {
  tester.view.physicalSize = const Size(1080, 2400);
  tester.view.devicePixelRatio = 3.0;
  addTearDown(tester.view.reset);
  await tester.pumpWidget(app);
  await tester.pumpAndSettle();
}

void main() {
  testWidgets('App starts', (tester) async {
    await openOnPhone(tester, const MyApp());
    expect(find.byType(MaterialApp), findsOneWidget);
  });

  testWidgets('Page "Welcome" fits a phone screen without errors', (tester) async {
    await openOnPhone(tester, const MaterialApp(home: WelcomePage()));
    expect(find.byType(WelcomePage), findsOneWidget);
  });

  testWidgets('Page "Sign in" fits a phone screen without errors', (tester) async {
    await openOnPhone(tester, const MaterialApp(home: SignInPage()));
    expect(find.byType(SignInPage), findsOneWidget);
  });

  testWidgets('Page "Home" fits a phone screen without errors', (tester) async {
    await openOnPhone(tester, const MaterialApp(home: HomePage()));
    expect(find.byType(HomePage), findsOneWidget);
  });

  testWidgets('Button "Get started" on Welcome opens Sign in', (tester) async {
    await openOnPhone(tester, const MyApp());
    final button = find.widgetWithText(ElevatedButton, 'Get started').first;
    await tester.ensureVisible(button);
    await tester.tap(button);
    await tester.pumpAndSettle();
    expect(find.byType(SignInPage), findsOneWidget);
  });

  testWidgets('Button "Sign in" on Sign in opens Home', (tester) async {
    await openOnPhone(tester, const MyApp());
    tester.state<NavigatorState>(find.byType(Navigator).first).pushNamed('/signin');
    await tester.pumpAndSettle();
    final button = find.widgetWithText(ElevatedButton, 'Sign in').first;
    await tester.ensureVisible(button);
    await tester.tap(button);
    await tester.pumpAndSettle();
    expect(find.byType(HomePage), findsOneWidget);
  });
}
